SELECT COUNT(*) FILTER (WHERE is_internal=FALSE) AS customers_total,
       COUNT(*) FILTER (WHERE is_internal=FALSE AND prefers_dark_mode=TRUE) AS dark_mode_enabled
FROM dim_users;

SELECT SUM(app_opens) AS total_opens, SUM(value_moments) AS total_value_moments, COUNT(*) AS user_days, COUNT(DISTINCT user_id) AS distinct_users
FROM fct_user_days
WHERE active_date BETWEEN '2026-07-06' AND '2026-07-12' AND is_internal=false;

SELECT COUNT(*) AS total_started_in_june
FROM fct_subscriptions
WHERE DATE_TRUNC('month', subscription_started_date) = DATE '2026-06-01';

SELECT COUNT(*) AS total_started_in_june
FROM fct_subscriptions
WHERE DATE_TRUNC('month', started_date) = DATE '2026-06-01';
